const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/budget_view_snapshots',
  qs: {
    project_id: 'SOME_INTEGER_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    'filters[budget_template_id]': 'SOME_ARRAY_VALUE',
    'filters[budget_view_id]': 'SOME_ARRAY_VALUE',
    'filters[snapshot_type]': 'SOME_STRING_VALUE',
    'filters[approval_status]': 'SOME_STRING_VALUE',
    sort: 'SOME_STRING_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/budget_view_snapshots?project_id=SOME_INTEGER_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&filters%5Bbudget_template_id%5D=SOME_ARRAY_VALUE&filters%5Bbudget_view_id%5D=SOME_ARRAY_VALUE&filters%5Bsnapshot_type%5D=SOME_STRING_VALUE&filters%5Bapproval_status%5D=SOME_STRING_VALUE&sort=SOME_STRING_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v1.0/budget_view_snapshots',
  headers: {'content-type': 'application/json'},
  body: {
    project_id: 10,
    budget_template_id: 99,
    budget_view_id: 99,
    name: 'New Year Budget',
    description: 'This is the budget snapshot for the new year',
    snapshot_type: 'ad_hoc',
    approval_status: 'approved',
    status_id: 12345,
    date_range_for_actuals: ['2024-01-01', '2024-12-31'],
    only_actuals_with_dates: false,
    financial_period_id: 42,
    reassign_financial_period: false
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/budget_view_snapshots"),
    Content = new StringContent("{\"project_id\":10,\"budget_template_id\":99,\"budget_view_id\":99,\"name\":\"New Year Budget\",\"description\":\"This is the budget snapshot for the new year\",\"snapshot_type\":\"ad_hoc\",\"approval_status\":\"approved\",\"status_id\":12345,\"date_range_for_actuals\":[\"2024-01-01\",\"2024-12-31\"],\"only_actuals_with_dates\":false,\"financial_period_id\":42,\"reassign_financial_period\":false}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

x-changelog.description:
The create response now includes the same nested `financial_period` object as the list
response. The scalar `financial_period_id` is now deprecated in favor of `financial_period`;
it is retained for backward compatibility.
